const item = $json.body || $json;
const headers = $input.item.json.headers || {};
const correlationId = headers['x-correlation-id'] || headers['x-request-id'] || 'trace_' + Date.now() + '_' + Math.random().toString(36).substr(2, 7);

const rawSender = item.from || (item.entry && item.entry[0]?.changes[0]?.value?.messages?.[0]?.from) || '';
const rawText = item.text?.body || item.message || item.prompt || (item.entry && item.entry[0]?.changes[0]?.value?.messages?.[0]?.text?.body) || '';
const eventType = item.event_type || item.type || (rawText ? 'text_message' : 'system_event');

return {
  json: {
    correlationId,
    eventType,
    sender: rawSender,
    content: rawText,
    rawPayload: item,
    ingestedAt: new Date().toISOString()
  }
};

